using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Threading;
using System.Windows.Forms;
using MC2Pack;
namespace Astera {
static partial class NetworkSelfTest {
 internal static int PrismRun(string root){try{
  if(Directory.Exists(root))throw new IOException("Use a new Prism audit directory");Directory.CreateDirectory(root);var checks=new List<string>();
  string fixture=Path.Combine(root,"full-pack-fixture");if(FullPackRun(fixture)!=0)throw new IOException(File.ReadAllText(Path.Combine(fixture,"failure.txt")));string bundle=Path.Combine(fixture,"release.zip");var release=Engine.Read(bundle);
  string data=Path.Combine(root,"Portable Prism"),custom=Path.Combine(root,"User Games");Directory.CreateDirectory(data);File.WriteAllText(Path.Combine(data,"prismlauncher.cfg"),"[General]\nInstanceDir="+custom.Replace('\\','/')+"\n");File.WriteAllText(Path.Combine(data,"accounts.json"),"account sentinel");
  var made=PrismProfiles.Create(data,release);var another=PrismProfiles.Create(data,release);Assert(made.Root!=another.Root&&Path.GetDirectoryName(made.Root)==custom,"Create overwrote an instance or ignored custom instances location");Assert(PrismProfiles.Discover(data).Count==2,"Prism instance discovery failed");Assert(Profiles.Read(made.Root).Path==made.GameRoot&&Profiles.Read(made.GameRoot).IsPrism,"Instance/game folder normalization failed");checks.Add("Prism instance creation, collision avoidance, custom instance directory and instance/game folder detection");
  string metadata=File.ReadAllText(Path.Combine(made.Root,"mmc-pack.json")),cfg=File.ReadAllText(Path.Combine(made.Root,"instance.cfg"));
  Engine.Runtime(made.GameRoot,release,false,new List<string>());
  foreach(string bad in new[]{metadata.Replace("26.3","1.21.1"),metadata.Replace("0.19.5","0.1.0"),metadata.Replace("net.fabricmc.fabric-loader","org.quiltmc.quilt-loader"),metadata.Replace("\"uid\":\"net.fabricmc.fabric-loader\"","\"disabled\":true,\"uid\":\"net.fabricmc.fabric-loader\"")}){File.WriteAllText(Path.Combine(made.Root,"mmc-pack.json"),bad);Reject(()=>Engine.Runtime(made.GameRoot,release,false,new List<string>()),"Wrong or disabled runtime was accepted");}File.WriteAllText(Path.Combine(made.Root,"mmc-pack.json"),metadata);
  Directory.CreateDirectory(Path.Combine(made.Root,"patches"));File.WriteAllText(Path.Combine(made.Root,"patches","net.minecraft.json"),"{}");Reject(()=>Engine.Runtime(made.GameRoot,release,false,new List<string>()),"Unverified custom runtime patch accepted");File.Delete(Path.Combine(made.Root,"patches","net.minecraft.json"));checks.Add("Minecraft version, minimum Fabric, disabled loader, conflicting loader and custom runtime patch checks");
  Put(made.GameRoot,"saves/keep/level.dat","world");Put(made.GameRoot,"config/pack.json","personal config");Put(made.GameRoot,"options.txt","music:0.23\nkey_key.forward:key.keyboard.up\nresourcePacks:[\"vanilla\"]\n");
  var plan=Engine.Scan(made.GameRoot,bundle,true,false,false,delegate{});Engine.Apply(plan,delegate{},true);Assert(File.Exists(Path.Combine(made.GameRoot,"mods","third-party.jar"))&&File.Exists(Path.Combine(made.GameRoot,"resourcepacks","pack.zip")),"Pack files installed outside active game root");Assert(!Directory.Exists(Path.Combine(made.Root,"mods")),"Mods installed beside Prism metadata");Assert(File.ReadAllText(Path.Combine(made.GameRoot,"saves","keep","level.dat"))=="world"&&File.ReadAllText(Path.Combine(made.GameRoot,"config","pack.json"))=="personal config","World or personal config changed");string options=File.ReadAllText(Path.Combine(made.GameRoot,"options.txt"));Assert(options.Contains("music:0.23")&&options.Contains("key.keyboard.up")&&options.Contains("file/pack.zip"),"Resource pack order/setup lost personal options");Assert(File.ReadAllText(Path.Combine(made.Root,"mmc-pack.json"))==metadata&&File.ReadAllText(Path.Combine(made.Root,"instance.cfg"))==cfg&&File.ReadAllText(Path.Combine(data,"accounts.json"))=="account sentinel","Prism metadata or account sentinel changed");checks.Add("Full pack installation targets minecraft/ and preserves worlds, personal config, keybinds, Prism metadata and account file");
  var repeat=Engine.Scan(made.GameRoot,bundle,true,false,false,delegate{});Assert(repeat.Edits.Count==0,"Repeat install rewrote the pack");File.AppendAllText(Path.Combine(made.Root,"instance.cfg"),"# changed since check\n");Reject(()=>Engine.Apply(repeat,delegate{},true),"Launcher metadata change after preview was not caught");File.WriteAllText(Path.Combine(made.Root,"instance.cfg"),cfg);checks.Add("Idempotent repeat install and runtime metadata changes rejected between preview and apply");
  var feed=new UpdateFeed{Schema=2,GameId="minecraft-squared",ExpiresUtc=DateTimeOffset.UtcNow.AddDays(1).ToUnixTimeSeconds(),Notes="Prism fixture",Release=release,RequiredMods=new List<RequiredMod>(),Sources=new List<PayloadSource>(),Bundle=new BundleSource{Url="https://example.com/pack.zip",Hash=Engine.Hash(bundle),Size=new FileInfo(bundle).Length}};var client=new UpdateClient("");client.Prepare(feed,made.GameRoot,Path.Combine(root,"cache"));checks.Add("The signed full-pack update planner accepts verified Prism runtime metadata");
  string legacy=Path.Combine(another.Root,".minecraft");Directory.Move(another.GameRoot,legacy);Assert(PrismProfiles.Read(legacy).GameRoot==legacy,"Legacy .minecraft layout not supported");Directory.CreateDirectory(another.GameRoot);Assert(PrismProfiles.Read(another.Root).GameRoot==another.GameRoot,"Prism's preferred minecraft folder precedence differs");checks.Add("Legacy .minecraft and modern minecraft folder precedence matches Prism");
  string binary=Path.Combine(root,"prismlauncher.exe");File.WriteAllBytes(binary,new byte[]{77,90});var start=PrismProfiles.Launch(binary,data,made.GameRoot);Assert(!start.UseShellExecute&&start.Arguments.Contains("--launch \""+made.Id+"\"")&&start.Arguments.Contains("--dir \""+data+"\""),"Prism CLI launch mapping is incorrect");Reject(()=>PrismProfiles.Launch(binary,Path.Combine(root,"other-library"),made.GameRoot),"Wrong Prism data root accepted");checks.Add("Play hands the correct quoted instance ID and launcher data directory to Prism, without account credentials");
  string setup=Path.Combine(root,"Minecraft2-Setup.zip");CurseForgeSetup.Create(release,setup);using(var zip=ZipFile.OpenRead(setup)){Assert(zip.Entries.Count==2&&zip.GetEntry("overrides/")!=null,"Setup ZIP contains unexpected files");using(var reader=new StreamReader(zip.GetEntry("manifest.json").Open())){string manifest=reader.ReadToEnd();Assert(manifest.Contains("fabric-"+release.Loader)&&manifest.Contains(release.Minecraft)&&manifest.Contains("\"files\":[]"),"CurseForge setup runtime differs from release");}}Reject(()=>CurseForgeSetup.Create(release,setup),"Existing setup ZIP overwritten");checks.Add("CurseForge setup export uses the verified Minecraft/Fabric versions and standard import format without overwriting existing ZIPs");
  Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);var prefs=new Preferences{Profile=made.GameRoot,PrismDataRoot=data,PrismExecutable=binary,MinecraftLauncher="prism"};using(var dialog=new MinecraftSettingsForm(prefs,"")){dialog.StartPosition=FormStartPosition.Manual;dialog.Location=new Point(-30000,-30000);dialog.Show();Application.DoEvents();Assert(dialog.LauncherChoice.SelectedIndex==1&&dialog.ProfilePath.Text==made.GameRoot,"Prism settings did not retain selected instance");using(var image=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(root,"settings.png"));}dialog.Close();}checks.Add("Minecraft settings retain Prism selection and render offscreen for review");
  File.WriteAllText(Path.Combine(root,"result.json"),Engine.Json.Serialize(new{Passed=true,Checks=checks,GameLaunched=false,LiveProfileChanged=false,AppSha256=Engine.Hash(Application.ExecutablePath)}));return 0;
 }catch(Exception error){Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"failure.txt"),error.ToString());return 1;}}
}
}
